-- ============================================================
-- Phase 16: Full 8-role RBAC Admin Portal & Live Platform CMS
-- - RBAC role gating (has_admin_role)
-- - Live CMS (platform settings, delivery zones, FAQs)
-- - Central Exam Authority console (dates/timetable/result-delay)
-- - Competition podium payout ledger
-- - Unified moderation queue (content + announcement reports)
-- - Audit log viewer (admin-gated)
-- - Google Workspace exam-calendar sync markers
-- All RPCs SECURITY DEFINER, error-JSON returns, no RAISE.
-- ============================================================

-- ---------- Schema extensions ----------

ALTER TABLE public.examination_sessions
  ADD COLUMN IF NOT EXISTS result_release_date timestamptz,
  ADD COLUMN IF NOT EXISTS result_delay_notice text,
  ADD COLUMN IF NOT EXISTS calendar_synced boolean NOT NULL DEFAULT false,
  ADD COLUMN IF NOT EXISTS calendar_event_id text;

CREATE TABLE IF NOT EXISTS public.faqs (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  question text NOT NULL,
  answer text NOT NULL,
  category text NOT NULL DEFAULT 'general',
  sort_order integer NOT NULL DEFAULT 0,
  is_active boolean NOT NULL DEFAULT true,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);

-- updated_at trigger for faqs
DROP TRIGGER IF EXISTS set_updated_at ON public.faqs;
CREATE TRIGGER set_updated_at BEFORE UPDATE ON public.faqs FOR EACH ROW EXECUTE FUNCTION public.trg_set_updated_at();

-- RLS: faqs readable by public, writable by admins
DROP POLICY IF EXISTS faqs_select_public ON public.faqs;
CREATE POLICY faqs_select_public ON public.faqs FOR SELECT TO public USING (true);
DROP POLICY IF EXISTS faqs_insert_admin ON public.faqs;
CREATE POLICY faqs_insert_admin ON public.faqs FOR INSERT WITH CHECK (public.is_admin_user());
DROP POLICY IF EXISTS faqs_update_admin ON public.faqs;
CREATE POLICY faqs_update_admin ON public.faqs FOR UPDATE USING (public.is_admin_user());
DROP POLICY IF EXISTS faqs_delete_admin ON public.faqs;
CREATE POLICY faqs_delete_admin ON public.faqs FOR DELETE USING (public.is_admin_user());

-- Seed FAQs (replace static JS FAQS with DB-backed defaults)
INSERT INTO public.faqs (question, answer, category, sort_order)
SELECT * FROM (VALUES
  ('What is VALENCE?', 'VALENCE is an all-in-one accounting study platform for ATSWA, ICAN and university accounting students in Nigeria, combining tuition, study materials, competitions and a professional community.', 'general', 1),
  ('How much does signup cost?', 'General platform signup is free. A one-time ₦3,000 tuition registration/unlock fee per level applies only when you apply for tuition and view full cost implications.', 'general', 2),
  ('How are ATSWA tuition fees calculated?', 'ATSWA online tuition is ₦20,000 per course with a 25% discount when selecting 2 or more courses (max ₦60,000 for all 4 courses), plus the ₦3,000 per-level unlock fee.', 'tuition', 3),
  ('How are ICAN tuition fees calculated?', 'ICAN online tuition is ₦40,000 per course with a 25% discount when selecting 3 or more courses, plus the ₦3,000 per-level unlock fee. Official ICAN fees are separate and never discounted.', 'tuition', 4),
