-- ============================================================
-- RPCs
-- ============================================================

-- 1. has_admin_role: fine-grained RBAC (super_admin bypasses)
CREATE OR REPLACE FUNCTION public.has_admin_role(p_role text DEFAULT NULL::text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $function$ DECLARE v_uid uuid; v_roles text[]; BEGIN SELECT auth.uid() INTO v_uid; SELECT array_agg(r.role) INTO v_roles FROM public.user_roles r WHERE r.user_id = v_uid; IF v_roles IS NOT NULL AND 'super_admin' = ANY(v_roles) THEN RETURN jsonb_build_object('allowed', true, 'roles', v_roles); END IF; IF p_role IS NOT NULL AND v_roles IS NOT NULL AND p_role = ANY(v_roles) THEN RETURN jsonb_build_object('allowed', true, 'roles', v_roles); END IF; RETURN jsonb_build_object('allowed', false, 'roles', COALESCE(v_roles, ARRAY[]::text[])); END; $function$;

-- 2. manage_platform_setting: upsert a CMS setting (admin-gated)
CREATE OR REPLACE FUNCTION public.manage_platform_setting(p_setting_key text DEFAULT NULL::text, p_setting_value jsonb DEFAULT NULL::jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $function$ DECLARE v_uid uuid; v_row public.platform_settings%ROWTYPE; BEGIN IF NOT is_admin_user() THEN RETURN jsonb_build_object('error', 'Admins only'); END IF; SELECT auth.uid() INTO v_uid; IF p_setting_key IS NULL OR trim(p_setting_key) = '' THEN RETURN jsonb_build_object('error', 'A setting key is required.'); END IF; SELECT * INTO v_row FROM public.platform_settings WHERE setting_key = p_setting_key; IF FOUND THEN UPDATE public.platform_settings SET setting_value = COALESCE(p_setting_value, setting_value), updated_at = now() WHERE setting_key = p_setting_key RETURNING id INTO v_row.id; ELSE INSERT INTO public.platform_settings (setting_key, setting_value) VALUES (p_setting_key, COALESCE(p_setting_value, 'null'::jsonb)) RETURNING id INTO v_row.id; END IF; INSERT INTO public.audit_logs (actor_user_id, action, entity_type, details) VALUES (v_uid, 'manage_platform_setting', 'platform_settings', jsonb_build_object('setting_key', p_setting_key, 'value', COALESCE(p_setting_value, 'null'::jsonb))); RETURN jsonb_build_object('status', 'ok', 'setting_key', p_setting_key, 'value', COALESCE(p_setting_value, 'null'::jsonb)); EXCEPTION WHEN OTHERS THEN RETURN jsonb_build_object('error', SQLERRM); END; $function$;

-- 3. fetch_all_platform_settings: CMS read (admin-gated)
CREATE OR REPLACE FUNCTION public.fetch_all_platform_settings() RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $function$ BEGIN IF NOT is_admin_user() THEN RETURN jsonb_build_object('error', 'Admins only'); END IF; RETURN (SELECT jsonb_agg(jsonb_build_object('id', s.id, 'setting_key', s.setting_key, 'setting_value', s.setting_value, 'description', s.description, 'updated_at', s.updated_at) ORDER BY s.setting_key ASC) FROM public.platform_settings s); EXCEPTION WHEN OTHERS THEN RETURN jsonb_build_object('error', SQLERRM); END; $function$;

-- 4. manage_delivery_zone: CRUD delivery zones (admin-gated)
CREATE OR REPLACE FUNCTION public.manage_delivery_zone(p_zone_id uuid DEFAULT NULL::uuid, p_name text DEFAULT NULL::text, p_states text[] DEFAULT NULL, p_fee_ngn int DEFAULT NULL::int, p_is_free boolean DEFAULT false) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $function$ DECLARE v_uid uuid; v_zone_id uuid; v_fee int; BEGIN IF NOT is_admin_user() THEN RETURN jsonb_build_object('error', 'Admins only'); END IF; SELECT auth.uid() INTO v_uid; IF p_name IS NULL OR trim(p_name) = '' THEN RETURN jsonb_build_object('error', 'A zone name is required.'); END IF; v_fee := COALESCE(p_fee_ngn, 0); IF p_is_free THEN v_fee := 0; END IF; IF p_zone_id IS NOT NULL THEN SELECT id INTO v_zone_id FROM public.delivery_zones WHERE id = p_zone_id; IF NOT FOUND THEN RETURN jsonb_build_object('error', 'Delivery zone not found.'); END IF; UPDATE public.delivery_zones SET name = p_name, states = COALESCE(p_states, states), fee_ngn = v_fee, is_free = p_is_free, updated_at = now() WHERE id = v_zone_id; ELSE v_zone_id := gen_random_uuid(); INSERT INTO public.delivery_zones (id, name, states, fee_ngn, is_free) VALUES (v_zone_id, p_name, COALESCE(p_states, ARRAY[]::text[]), v_fee, p_is_free); END IF; INSERT INTO public.audit_logs (actor_user_id, action, entity_type, entity_id, details) VALUES (v_uid, 'manage_delivery_zone', 'delivery_zones', v_zone_id, jsonb_build_object('name', p_name, 'fee_ngn', v_fee, 'is_free', p_is_free)); RETURN jsonb_build_object('status', 'ok', 'zone_id', v_zone_id, 'name', p_name, 'fee_ngn', v_fee, 'is_free', p_is_free); EXCEPTION WHEN OTHERS THEN RETURN jsonb_build_object('error', SQLERRM); END; $function$;

-- 5. manage_exam_session: Central Exam Authority update (admin-gated)
CREATE OR REPLACE FUNCTION public.manage_exam_session(p_session_id uuid DEFAULT NULL::uuid, p_name text DEFAULT NULL::text, p_diet text DEFAULT NULL::text, p_year int DEFAULT NULL::int, p_registration_opens timestamptz DEFAULT NULL, p_registration_closes timestamptz DEFAULT NULL, p_exam_starts timestamptz DEFAULT NULL, p_exam_ends timestamptz DEFAULT NULL, p_fee_payment_deadline timestamptz DEFAULT NULL, p_tuition_commencement timestamptz DEFAULT NULL, p_revision_starts timestamptz DEFAULT NULL, p_revision_ends timestamptz DEFAULT NULL, p_mock_exam_date timestamptz DEFAULT NULL, p_class_schedule_start timestamptz DEFAULT NULL, p_status text DEFAULT NULL::text, p_result_release_date timestamptz DEFAULT NULL, p_result_delay_notice text DEFAULT NULL::text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $function$ DECLARE v_uid uuid; v_exists boolean; BEGIN IF NOT is_admin_user() THEN RETURN jsonb_build_object('error', 'Admins only'); END IF; SELECT auth.uid() INTO v_uid; IF p_session_id IS NULL THEN RETURN jsonb_build_object('error', 'A session id is required to update an exam session.'); END IF; SELECT EXISTS(SELECT 1 FROM public.examination_sessions WHERE id = p_session_id) INTO v_exists; IF NOT v_exists THEN RETURN jsonb_build_object('error', 'Exam session not found.'); END IF; UPDATE public.examination_sessions SET name = COALESCE(p_name, name), diet = COALESCE(p_diet, diet), year = COALESCE(p_year, year), registration_opens = COALESCE(p_registration_opens, registration_opens), registration_closes = COALESCE(p_registration_closes, registration_closes), exam_starts = COALESCE(p_exam_starts, exam_starts), exam_ends = COALESCE(p_exam_ends, exam_ends), fee_payment_deadline = COALESCE(p_fee_payment_deadline, fee_payment_deadline), tuition_commencement = COALESCE(p_tuition_commencement, tuition_commencement), revision_starts = COALESCE(p_revision_starts, revision_starts), revision_ends = COALESCE(p_revision_ends, revision_ends), mock_exam_date = COALESCE(p_mock_exam_date, mock_exam_date), class_schedule_start = COALESCE(p_class_schedule_start, class_schedule_start), status = COALESCE(p_status, status), result_release_date = COALESCE(p_result_release_date, result_release_date), result_delay_notice = COALESCE(p_result_delay_notice, result_delay_notice), updated_at = now() WHERE id = p_session_id; INSERT INTO public.audit_logs (actor_user_id, action, entity_type, entity_id, details) VALUES (v_uid, 'manage_exam_session', 'examination_sessions', p_session_id, jsonb_build_object('name', COALESCE(p_name, ''), 'status', COALESCE(p_status, ''), 'result_release_date', COALESCE(p_result_release_date::text, ''), 'result_delay_notice', COALESCE(p_result_delay_notice, ''))); RETURN jsonb_build_object('status', 'ok', 'session_id', p_session_id, 'message', 'Exam session updated'); EXCEPTION WHEN OTHERS THEN RETURN jsonb_build_object('error', SQLERRM); END; $function$;

-- 6. fetch_exam_authority_console: all sessions + result-delay (admin-gated)
CREATE OR REPLACE FUNCTION public.fetch_exam_authority_console() RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $function$ DECLARE v_rows jsonb; BEGIN IF NOT is_admin_user() THEN RETURN jsonb_build_object('error', 'Admins only'); END IF; SELECT jsonb_agg(jsonb_build_object('id', s.id, 'name', s.name, 'diet', s.diet, 'year', s.year, 'status', s.status, 'registration_opens', s.registration_opens, 'registration_closes', s.registration_closes, 'exam_starts', s.exam_starts, 'exam_ends', s.exam_ends, 'fee_payment_deadline', s.fee_payment_deadline, 'tuition_commencement', s.tuition_commencement, 'revision_starts', s.revision_starts, 'revision_ends', s.revision_ends, 'mock_exam_date', s.mock_exam_date, 'class_schedule_start', s.class_schedule_start, 'result_release_date', s.result_release_date, 'result_delay_notice', s.result_delay_notice, 'calendar_synced', s.calendar_synced, 'calendar_event_id', s.calendar_event_id, 'programme_name', p.name, 'updated_at', s.updated_at) ORDER BY s.year DESC NULLS LAST, s.name ASC) INTO v_rows FROM public.examination_sessions s LEFT JOIN public.programmes p ON p.id = s.programme_id WHERE s.is_archived = false; RETURN jsonb_build_object('sessions', COALESCE(v_rows, '[]'::jsonb)); EXCEPTION WHEN OTHERS THEN RETURN jsonb_build_object('error', SQLERRM); END; $function$;

-- 7. sync_exam_calendar: mark an exam session synced to Google Calendar (admin-gated)
CREATE OR REPLACE FUNCTION public.sync_exam_calendar(p_session_id uuid DEFAULT NULL::uuid, p_calendar_event_id text DEFAULT NULL::text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $function$ DECLARE v_uid uuid; v_exists boolean; v_payload jsonb; BEGIN IF NOT is_admin_user() THEN RETURN jsonb_build_object('error', 'Admins only'); END IF; SELECT auth.uid() INTO v_uid; IF p_session_id IS NULL THEN RETURN jsonb_build_object('error', 'A session id is required.'); END IF; SELECT EXISTS(SELECT 1 FROM public.examination_sessions WHERE id = p_session_id) INTO v_exists; IF NOT v_exists THEN RETURN jsonb_build_object('error', 'Exam session not found.'); END IF; UPDATE public.examination_sessions SET calendar_synced = true, calendar_event_id = COALESCE(p_calendar_event_id, calendar_event_id), updated_at = now() WHERE id = p_session_id RETURNING jsonb_build_object('id', id, 'name', name, 'exam_starts', exam_starts, 'exam_ends', exam_ends) INTO v_payload; INSERT INTO public.audit_logs (actor_user_id, action, entity_type, entity_id, details) VALUES (v_uid, 'sync_exam_calendar', 'examination_sessions', p_session_id, jsonb_build_object('calendar_event_id', COALESCE(p_calendar_event_id, ''))); RETURN jsonb_build_object('status', 'ok', 'session_id', p_session_id, 'calendar_synced', true, 'calendar_event_id', COALESCE(p_calendar_event_id, ''), 'event', v_payload); EXCEPTION WHEN OTHERS THEN RETURN jsonb_build_object('error', SQLERRM); END; $function$;

-- 8. fetch_podium_ledger: competition reward disbursement ledger (admin-gated)
CREATE OR REPLACE FUNCTION public.fetch_podium_ledger(p_competition_id uuid DEFAULT NULL::uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $function$ DECLARE v_rows jsonb; v_competition_name text; BEGIN IF NOT is_admin_user() THEN RETURN jsonb_build_object('error', 'Admins only'); END IF; IF p_competition_id IS NOT NULL THEN SELECT name INTO v_competition_name FROM public.competitions WHERE id = p_competition_id; END IF; SELECT jsonb_agg(jsonb_build_object('id', r.id, 'competition_id', r.competition_id, 'competition_name', c.name, 'profile_id', r.profile_id, 'display_name', pr.display_name, 'institution_id', r.institution_id, 'institution_name', i.name, 'placement_rank', r.placement_rank, 'prize_amount_ngn', r.prize_amount_ngn, 'status', r.status, 'disbursed_at', r.disbursed_at, 'audited_by', r.audited_by, 'award_name', aw.award_name, 'award_type', aw.award_type, 'created_at', r.created_at) ORDER BY r.placement_rank ASC NULLS LAST, r.prize_amount_ngn DESC NULLS LAST) INTO v_rows FROM public.competition_rewards r JOIN public.competitions c ON c.id = r.competition_id LEFT JOIN public.profiles pr ON pr.id = r.profile_id LEFT JOIN public.institutions i ON i.id = r.institution_id LEFT JOIN public.competition_awards aw ON aw.competition_id = r.competition_id AND aw.profile_id = r.profile_id AND aw.award_type = 'podium' WHERE (p_competition_id IS NULL OR r.competition_id = p_competition_id); RETURN jsonb_build_object('competition_name', COALESCE(v_competition_name, 'All competitions'), 'ledger', COALESCE(v_rows, '[]'::jsonb)); EXCEPTION WHEN OTHERS THEN RETURN jsonb_build_object('error', SQLERRM); END; $function$;

-- 9. fetch_moderation_queue: unified content + announcement reports (admin-gated)
CREATE OR REPLACE FUNCTION public.fetch_moderation_queue() RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $function$ DECLARE v_rows jsonb; BEGIN IF NOT is_admin_user() THEN RETURN jsonb_build_object('error', 'Admins only'); END IF; SELECT jsonb_agg(jsonb_build_object('id', r.id, 'source', 'content', 'target_type', r.target_type, 'target_id', r.target_id, 'reason', r.reason, 'description', r.description, 'status', r.status, 'reporter_profile_id', r.reporter_profile_id, 'reviewed_by', r.reviewed_by, 'created_at', r.created_at) ORDER BY r.created_at DESC) INTO v_rows FROM public.content_reports r WHERE r.status = 'pending'; RETURN jsonb_build_object('content_reports', COALESCE(v_rows, '[]'::jsonb)); EXCEPTION WHEN OTHERS THEN RETURN jsonb_build_object('error', SQLERRM); END; $function$;

-- 10. fetch_announcement_moderation_queue: announcement reports (admin-gated)
CREATE OR REPLACE FUNCTION public.fetch_announcement_moderation_queue() RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $function$ DECLARE v_rows jsonb; BEGIN IF NOT is_admin_user() THEN RETURN jsonb_build_object('error', 'Admins only'); END IF; SELECT jsonb_agg(jsonb_build_object('id', r.id, 'source', 'announcement', 'announcement_id', r.announcement_id, 'announcement_title', a.title, 'reason', r.reason, 'status', r.status, 'reporter_profile_id', r.reporter_profile_id, 'reviewed_by', r.reviewed_by, 'created_at', r.created_at) ORDER BY r.created_at DESC) INTO v_rows FROM public.announcement_reports r LEFT JOIN public.announcement_posts a ON a.id = r.announcement_id WHERE r.status = 'pending'; RETURN jsonb_build_object('announcement_reports', COALESCE(v_rows, '[]'::jsonb)); EXCEPTION WHEN OTHERS THEN RETURN jsonb_build_object('error', SQLERRM); END; $function$;

-- 11. resolve_moderation_report: resolve a content report (admin-gated)
CREATE OR REPLACE FUNCTION public.resolve_moderation_report(p_report_id uuid DEFAULT NULL::uuid, p_action text DEFAULT NULL::text, p_notes text DEFAULT NULL::text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $function$ DECLARE v_uid uuid; v_profile_id uuid; v_action text; v_found boolean; BEGIN IF NOT is_admin_user() THEN RETURN jsonb_build_object('error', 'Admins only'); END IF; SELECT auth.uid() INTO v_uid; IF p_action NOT IN ('uphold', 'dismiss') THEN RETURN jsonb_build_object('error', 'Action must be uphold or dismiss.'); END IF; v_action := p_action; SELECT EXISTS(SELECT 1 FROM public.content_reports WHERE id = p_report_id) INTO v_found; IF NOT v_found THEN RETURN jsonb_build_object('error', 'Content report not found.'); END IF; SELECT id INTO v_profile_id FROM public.profiles WHERE user_id = v_uid LIMIT 1; UPDATE public.content_reports SET status = v_action, reviewed_by = v_profile_id, updated_at = now() WHERE id = p_report_id; INSERT INTO public.audit_logs (actor_user_id, action, entity_type, entity_id, details) VALUES (v_uid, 'resolve_moderation_report', 'content_reports', p_report_id, jsonb_build_object('action', v_action, 'notes', COALESCE(p_notes, ''))); RETURN jsonb_build_object('status', 'ok', 'report_id', p_report_id, 'action', v_action); EXCEPTION WHEN OTHERS THEN RETURN jsonb_build_object('error', SQLERRM); END; $function$;

-- 12. resolve_announcement_report: resolve an announcement report (admin-gated)
CREATE OR REPLACE FUNCTION public.resolve_announcement_report(p_report_id uuid DEFAULT NULL::uuid, p_action text DEFAULT NULL::text, p_notes text DEFAULT NULL::text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $function$ DECLARE v_uid uuid; v_action text; v_found boolean; v_announcement_id uuid; BEGIN IF NOT is_admin_user() THEN RETURN jsonb_build_object('error', 'Admins only'); END IF; SELECT auth.uid() INTO v_uid; IF p_action NOT IN ('uphold', 'dismiss') THEN RETURN jsonb_build_object('error', 'Action must be uphold or dismiss.'); END IF; v_action := p_action; SELECT announcement_id INTO v_announcement_id FROM public.announcement_reports WHERE id = p_report_id; IF v_announcement_id IS NULL THEN RETURN jsonb_build_object('error', 'Announcement report not found.'); END IF; UPDATE public.announcement_reports SET status = v_action, reviewed_by = v_uid, reviewed_at = now(), updated_at = now() WHERE id = p_report_id; IF v_action = 'uphold' THEN UPDATE public.announcement_posts SET status = 'removed', updated_at = now() WHERE id = v_announcement_id; END IF; INSERT INTO public.audit_logs (actor_user_id, action, entity_type, entity_id, details) VALUES (v_uid, 'resolve_announcement_report', 'announcement_reports', p_report_id, jsonb_build_object('action', v_action, 'announcement_id', v_announcement_id, 'notes', COALESCE(p_notes, ''))); RETURN jsonb_build_object('status', 'ok', 'report_id', p_report_id, 'action', v_action); EXCEPTION WHEN OTHERS THEN RETURN jsonb_build_object('error', SQLERRM); END; $function$;

-- 13. fetch_admin_audit_logs: audit log viewer (admin-gated, paginated)
CREATE OR REPLACE FUNCTION public.fetch_admin_audit_logs(p_limit int DEFAULT 100, p_offset int DEFAULT 0) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $function$ DECLARE v_rows jsonb; BEGIN IF NOT is_admin_user() THEN RETURN jsonb_build_object('error', 'Admins only'); END IF; SELECT jsonb_agg(jsonb_build_object('id', a.id, 'action', a.action, 'entity_type', a.entity_type, 'entity_id', a.entity_id, 'details', a.details, 'actor_user_id', a.actor_user_id, 'actor_display_name', pr.display_name, 'actor_email', (SELECT email FROM auth.users WHERE id = a.actor_user_id), 'created_at', a.created_at) ORDER BY a.created_at DESC) INTO v_rows FROM (SELECT * FROM public.audit_logs ORDER BY created_at DESC LIMIT COALESCE(p_limit, 100) OFFSET COALESCE(p_offset, 0)) a LEFT JOIN public.profiles pr ON pr.id = a.actor_profile_id; RETURN jsonb_build_object('logs', COALESCE(v_rows, '[]'::jsonb)); EXCEPTION WHEN OTHERS THEN RETURN jsonb_build_object('error', SQLERRM); END; $function$;

-- 14. manage_faq: CRUD FAQs (admin-gated)
CREATE OR REPLACE FUNCTION public.manage_faq(p_faq_id uuid DEFAULT NULL::uuid, p_question text DEFAULT NULL::text, p_answer text DEFAULT NULL::text, p_category text DEFAULT 'general'::text, p_sort_order int DEFAULT 0, p_is_active boolean DEFAULT true) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $function$ DECLARE v_uid uuid; v_faq_id uuid; BEGIN IF NOT is_admin_user() THEN RETURN jsonb_build_object('error', 'Admins only'); END IF; SELECT auth.uid() INTO v_uid; IF p_question IS NULL OR trim(p_question) = '' THEN RETURN jsonb_build_object('error', 'A question is required.'); END IF; IF p_answer IS NULL OR trim(p_answer) = '' THEN RETURN jsonb_build_object('error', 'An answer is required.'); END IF; IF p_faq_id IS NOT NULL THEN SELECT id INTO v_faq_id FROM public.faqs WHERE id = p_faq_id; IF NOT FOUND THEN RETURN jsonb_build_object('error', 'FAQ not found.'); END IF; UPDATE public.faqs SET question = p_question, answer = p_answer, category = COALESCE(p_category, category), sort_order = COALESCE(p_sort_order, sort_order), is_active = COALESCE(p_is_active, is_active), updated_at = now() WHERE id = v_faq_id; ELSE v_faq_id := gen_random_uuid(); INSERT INTO public.faqs (id, question, answer, category, sort_order, is_active) VALUES (v_faq_id, p_question, p_answer, COALESCE(p_category, 'general'), COALESCE(p_sort_order, 0), COALESCE(p_is_active, true)); END IF; INSERT INTO public.audit_logs (actor_user_id, action, entity_type, entity_id, details) VALUES (v_uid, 'manage_faq', 'faqs', v_faq_id, jsonb_build_object('question', p_question, 'category', COALESCE(p_category, 'general'))); RETURN jsonb_build_object('status', 'ok', 'faq_id', v_faq_id); EXCEPTION WHEN OTHERS THEN RETURN jsonb_build_object('error', SQLERRM); END; $function$;

-- 15. fetch_faqs: public FAQ list (active, ordered)
CREATE OR REPLACE FUNCTION public.fetch_faqs(p_category text DEFAULT NULL::text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $function$ DECLARE v_rows jsonb; BEGIN SELECT jsonb_agg(jsonb_build_object('id', f.id, 'question', f.question, 'answer', f.answer, 'category', f.category, 'sort_order', f.sort_order) ORDER BY f.sort_order ASC, f.created_at ASC) INTO v_rows FROM public.faqs f WHERE f.is_active = true AND (p_category IS NULL OR f.category = p_category); RETURN COALESCE(v_rows, '[]'::jsonb); EXCEPTION WHEN OTHERS THEN RETURN jsonb_build_object('error', SQLERRM); END; $function$;
